INSERT INTO public.form_schemas (id, table_title, columns, updated_at)
VALUES
  ('form_01', 'ቅጽ 01፡ በ{year} በጀት ዓመት በየደረጃው የተዋቀረ የኮሚሽን መዋቅር የሚያሳይ ሠንጠረዥ', '[{"key":"ክ/ከተማ ተጠሪ የሆኑ ወረዳዎች","subKeys":["ብዛት","ያዋቀሩ","ያላዋቀሩ"]},{"key":"ለወረዳ ተጠሪ የሆኑ ቀበሌዎች","subKeys":["ብዛት","ያዋቀሩ","ያላዋቀሩ"]},{"key":"በብልፅግና ህብረት ደረጃ","subKeys":["ብዛት","ያዋቀሩ","ያላዋቀሩ"]},{"key":"ጠቅላላ ድምር","subKeys":["ብዛት","ያዋቀሩ","ያላዋቀሩ"]},{"key":"ያዋቀሩ %","subKeys":[]}]'::jsonb, NOW()),
  ('form_02', 'ቅጽ 02፡ በ{year} በጀት ዓመት በየደረጃው የሚገኙ የኮሚሽን አባላት የሚያሳይ ሠንጠረዥ', '[{"key":"የክፍለ-ክ/ከተማ ኮሚሽን","subKeys":["ወ","ሴ","ድ"]},{"key":"የወረዳ ኮሚሽን","subKeys":["ወ","ሴ","ድ"]},{"key":"የቀበሌ ኮሚሽን","subKeys":["ወ","ሴ","ድ"]},{"key":"የብልፅግና ህብረት ኮሚሽን","subKeys":["ወ","ሴ","ድ"]},{"key":"ጠቅላላ ድምር","subKeys":["ወ","ሴ","ድ"]}]'::jsonb, NOW()),
  ('form_03', 'ቅጽ 03፡ በ{year} በጀት ዓመት የኮሚሽኑ ቅርንጫፍ ጽ/ቤቶች ቋሚ የሰው ሀይል የሚያሳይ ሠንጠረዥ', '[{"key":"የክ/ከተማ ኮሚሽን ጽ/ቤት","subKeys":["ጽ/ኃ","ም/ክ","ባለሙ","ጸሐ","ሹፌ","ድም"]},{"key":"የዞን/ክ/ከተማ/ልዩ ወረዳ ኮሚሽን ጽ/ቤት","subKeys":["ጽ/ኃ","ም/ክ","ባለሙ","ጸሐ","ሹፌ","ድም"]},{"key":"የወረዳ/ክ/ከተማ ኮሚሽን ጽ/ቤት","subKeys":["ጽ/ኃ","ም/ክ","ባለሙ","ጸሐ","ሹፌ","ድም"]},{"key":"ጠቅላላ ድምር","subKeys":["ጽ/ኃ","ም/ክ","ባለሙ","ጸሐ","ሹፌ","ድም"]}]'::jsonb, NOW()),
  ('form_04', 'ቅጽ 04፡ በ{year} በጀት ዓመት የኮሚሽን ቅርንጫፍ ጽ/ቤቶች የስራ ክፍል የሚያሣይ ሠንጠረዥ', '[{"key":"የክ/ከተማ ቅርንጫፍ ጽ/ቤት","subKeys":["እቅድ","ክንውን","%"]},{"key":"የክፍለ-ክ/ከተማ ቅር/ጽ/ቤት","subKeys":["እቅድ","ክንውን","%"]},{"key":"የወረዳ ቅ/ጽ/ቤት","subKeys":["እቅድ","ክንውን","%"]},{"key":"ጠቅላላ ድምር","subKeys":["እቅድ","ክንውን","%"]}]'::jsonb, NOW()),
  ('form_05', 'ቅጽ 05፡ በ{year} በጀት ዓመት በየደረጃው ለሚገኙ የኮሚሽን መዋቅሮች የተመደበ በጀት የሚያሳይ ሠንጠረዥ', '[{"key":"አቃቂ ክ/ከተማ","subKeys":["ብር","ሣ"]},{"key":"ክ/ከተማ","subKeys":["ብር","ሣ"]},{"key":"ለወረዳ","subKeys":["ብር","ሣ"]},{"key":"ጠቅላላ ድምር","subKeys":["ብር","ሣ"]}]'::jsonb, NOW()),
  ('form_06', 'ቅጽ 06፡ የ{year} በጀት ዓመት እቅድ የከለሱ በየደረጃው የሚገኙ የኮሚሽን መዋቅሮች የሚያሳይ ሠንጠረዥ', '[{"key":"የክ/ከተማ ኮሚሽን","subKeys":["እቅድ","ክንውን","%"]},{"key":"የክፍለ-ክ/ከተማ ኮሚሽን","subKeys":["እቅድ","ክንውን","%"]},{"key":"ወረዳ/ክ/ከተማ ኮሚሽን","subKeys":["እቅድ","ክንውን","%"]},{"key":"በቀበሌ ኮሚሽን","subKeys":["እቅድ","ክንውን","%"]},{"key":"በብልጽግና ህብረት ኮሚሽን","subKeys":["እቅድ","ክንውን","%"]},{"key":"አጠቃላይ ድምር","subKeys":["እቅድ","ክንውን","%"]}]'::jsonb, NOW()),
  ('form_06_1', 'ቅጽ 06-1፡ የ{year} በጀት ዓመት እቅድ ላይ ኦሬንቴሽን የሰጡ የኮሚሽን መዋቅሮች የሚያሳይ ሠንጠረዥ', '[{"key":"ክ/ከተማ","subKeys":["እቅድ","ክንውን","%"]},{"key":"ክፍለ-ክ/ከተማ","subKeys":["እቅድ","ክንውን","%"]},{"key":"ወረዳ","subKeys":["እቅድ","ክንውን","%"]},{"key":"በቀበሌ ኮሚሽን","subKeys":["እቅድ","ክንውን","%"]},{"key":"በብልጽግና ህብረት ኮሚሽን","subKeys":["እቅድ","ክንውን","%"]},{"key":"ጠቅላላ ድምር","subKeys":["እቅድ","ክንውን","%"]}]'::jsonb, NOW()),
  ('form_06_2', 'ቅጽ 06-2፡ በ{year} በጀት ዓመት በተከለሰ እቅድ ኦሬንቴሽን ላይ የተሳተፉ የኮሚሽን ቤተሠብ ብዛት የሚየሳይ ሠንጠረዥ', '[{"key":"በክ/ከተማ ደረጃ","subKeys":["ወ","ሴ","ድ"]},{"key":"በክፍለ-ክ/ከተማ ደረጃ","subKeys":["ወ","ሴ","ድ"]},{"key":"በወረዳ ደረጃ","subKeys":["ወ","ሴ","ድ"]},{"key":"በቀበሌ ኮሚሽን","subKeys":["ወ","ሴ","ድ"]},{"key":"በብልጽግና ህብረት ኮሚሽን","subKeys":["ወ","ሴ","ድ"]},{"key":"ጠቅላላ ድምር","subKeys":["ወ","ሴ","ድ"]},{"key":"በበጀት ዓመት ከቅጽ 2 እና 3 በመቶኛ (%)","subKeys":[]}]'::jsonb, NOW()),
  ('form_07', 'ቅጽ 07፡ በ{year} በጀት ዓመት ሪፖርት በየደረጃው ለሚገኙ የኮሚሽን መዋቅሮች የቀረቡ የሚያሳይ ሠንጠረዥ', '[{"key":"ለክተማ የላኩ ክፍለ-ከተሞች","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"ክ/ከተማ የላኩ","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"ለወረዳ/ክ/ከተማ የላኩ ቀበሌዎች","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"ለወረዳ የላኩ የብልጽግና ህብረት","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"አጠቃላይ ድምር","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"ለብልጽግና ህብረት ኮንፈረንስ ሪፖርት ያቀረቡ ኮሚሽን","subKeys":["ብዛት","%"]}]'::jsonb, NOW()),
  ('form_08', 'ቅጽ 08፡ በ{year} በጀት ዓመት ሱፐርቪዥን/ኢንስፔክሽን ያካሄዱ የኮሚሽን መዋቅሮች ብዛት የሚያሳይ ሠንጠረዥ', '[{"key":"በክ/ከተማ","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"በክፍለ-ክ/ከተማ","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"በወረዳ/ክ/ከተማ","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"በቀበሌዎች","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"በብልጽግና ህብረት","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"አጠቃላይ ድምር","subKeys":["ዕቅድ","ክንውን","%"]}]'::jsonb, NOW()),
  ('form_09', 'ቅጽ 09፡ በ{year} በጀት ዓመት ሱፐርቪዥን/ኢንስፔክሽን ካካሄዱት መዋቅሮች የግኝቶች ግብረ-መልስ ለፓርቲ ቅ/ጽ/ቤቶች የሰጡ የሚያሳይ ሠንጠረዥ', '[{"key":"በክ/ከተማ ደረጃ","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"በዞን/ክ/ከተማ/ልዩ ወረዳ ደረጃ","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"በወረዳ/ክ/ከተማ ደረጃ","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"በቀበሌ ደረጃ","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"በብልጽግና ህብረት ደረጃ","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"አጠቃላይ ድምር","subKeys":["ዕቅድ","ክንውን","%"]}]'::jsonb, NOW()),
  ('form_10', 'ቅጽ 10፡ በ{year} በጀት ዓመት ግምገማ ያካሄዱ የኮሚሽን መዋቅሮች ብዛት የሚያሳይ ሠንጠረዥ', '[{"key":"በክ/ከተማ ደረጃ","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"በዞን/ክ/ከተማ/ልዩ ወረዳ ደረጃ","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"በወረዳ/ክ/ከተማ ደረጃ","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"በቀበሌ ደረጃ","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"በብልጽግና ህብረት ደረጃ","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"አጠቃላይ ድምር","subKeys":["ዕቅድ","ክንውን","%"]}]'::jsonb, NOW()),
  ('form_11', 'ቅጽ 11፡ በ{year} በጀት ዓመት የ1ኛ መንፈቅ ዓመት ምዘና ያካሄዱ የኮሚሽን መዋቅሮች፣ የተሳተፉ ብዛትና የተሰጠ ውጤት የሚያሳይ ሠንጠረዥ', '[{"key":"ምዘና ያካሄዱ የኮሚሽን መዋቅር ብዛት","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"በምዛና የተሳተፉ የኮሚሽን አባላት ብዛት","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"በምዛና የተሳተፉ የኮሚሽን ቅ/ጽ/ቤት ኃላፊዎችና ሠራተኞች ብዛት","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"በጠቅላላ በምዘና የተሳተፉ የኮሚሽን ቤተሰብ ብዛት","subKeys":["ዕቅድ","ክንውን","%"]},{"key":"በጠቅላላ የተሰጠ የምዘና ውጤት","subKeys":["በጣም ከፍተኛ","ከፍተኛ","መካከለኛ","ዝቅተኛ","በጣም ዝቅተኛ","ድምር"]}]'::jsonb, NOW()),
  ('form_12', 'ቅጽ 12፡ በ{year} በጀት ዓመት ለኮሚሽን ጽ/ቤት ኃላፊዎችና ለኮሚሽን አባላት የተሰጡ የግንዛቤ ማስጨበጫ ስልጠና የሚያሳይ ሠንጠረዥ', '[{"key":"በክ/ከተማ ደረጃ","subKeys":["ወ","ሴ","ድ"]},{"key":"በክፍለ-ክ/ከተማ ደረጃ","subKeys":["ወ","ሴ","ድ"]},{"key":"በወረዳ ደረጃ","subKeys":["ወ","ሴ","ድ"]},{"key":"በቀበሌ ኮሚሽን","subKeys":["ወ","ሴ","ድ"]},{"key":"በብልጽግና ህብረት ኮሚሽን","subKeys":["ወ","ሴ","ድ"]},{"key":"አጠቃላይ ድምር","subKeys":["ወ","ሴ","ድ"]},{"key":"በበጀት ዓመቱ በቅጽ 2 እና 3 ጠቅላላ ድምር ውስጥ ስልጠና የወሰዱ","subKeys":["እቅድ","በመቶኛ"]}]'::jsonb, NOW()),
