  ('form_23', 'ቅጽ 23፡ በ{year} በጀት ዓመት በዘጠኝ ወሩ በኮሚሽኑ የተመዘገቡ ውጤቶች አፈጻጸም የሚያሳይ ሠንጠረዥ', '[{"key":"የኢንስፔክሽን ግኝቶች የአሰራር ጥሰቶች ብዛት","subKeys":[]},{"key":"ከአባልነት ተሰናብተው የተመለሱ አባላት ብዛት","subKeys":[]},{"key":"ከኃላፊነት ተነስተው የተመለሱ አመራሮች ብዛት","subKeys":[]},{"key":"በኢንስፔክሽን የተገኘ የፓርቲ መዋጮ የማይከፍሉ አባላት","subKeys":["ብዛት","ብር"]},{"key":"የተመለሰ የፓርቲ ገንዘብ ብዛት በብር","subKeys":[]},{"key":"ኦዲት እንዲያስደርጉ የተደረገ የፓርቲ ቅ/ጽ/ቤቶች ብዛት","subKeys":[]},{"key":"እንዲመለስ የተደረገ የኦዲት ግኝቶች በብር","subKeys":[]},{"key":"እንዲመዘግቡ የተደረገ የፓርቲ ንብረት ብዛት","subKeys":[]},{"key":"የንብረት ባለቤትነት ሰነድ እንዲወጣላቸው የተደረገ ብዛት","subKeys":[]},{"key":"በፀረ-ሙስና ንቅናቄ የተመዘገበ ውጤት","subKeys":["ሀብት ማስመዝገብ","የተመለሰ ገንዘብ","ለህግ የቀረበ"]}]'::jsonb, NOW()),
  ('form_24', 'ቅጽ 24፡ በ{year} በጀት ዓመት ከኮሚሽን ቅርንጫፍ ጽ/ቤቶች የተነሱ/የወጡ ኃላፊዎች መከታተያ ሠንጠረዥ', '[{"key":"የክፍለ-ክ/ከተማ ቅ/ጽ/ቤት","subKeys":["በሹመት","በድክመት","ድምር"]},{"key":"የወረዳ ቅ/ጽ/ቤት","subKeys":["በሹመት","በድክመት","ድምር"]},{"key":"ጠቅላላ ድምር","subKeys":["በሹመት","በድክመት","ድምር"]},{"key":"በድክመት ከተነሱት","subKeys":["አሰራር ጠብቆ","አሰራር ሳይጠብቅ","ድምር"]}]'::jsonb, NOW()),
